// Reproducible README screenshots: the real React UI (light Nokia theme, Russian) on synthetic data.
// Nothing here is a phone or Nokia firmware: a stub transport answers as an identified E52/E72, a test
// volume provides files, firmware ZIPs and packages are generated by the unit-test builders.
//   node tools/capture_screenshots.cjs [outDir]    (default: docs/screenshots)
const { chromium } = require("playwright");
const fs = require("fs"), os = require("os"), path = require("path");
const repo = path.resolve(__dirname, ".."), python = process.env.SYMPORT_PYTHON || "python3";
const out = path.resolve(process.argv[2] || path.join(repo, "docs/screenshots"));
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "symport-shots-"));
fs.mkdirSync(out, { recursive: true });

const { prepare, start, stop: stopFixture } = require("./lib/fixture.cjs");
prepare(tmp);
let lastPage;
const shot = async (page, name, options = {}) => {
  await page.evaluate(() => window.scrollTo(0, 0)); // sticky sidebar must sit in the corner of the capture
  await page.mouse.move(640, 430); // no tooltip of the last hovered control in the picture
  await page.waitForTimeout(400);
  await page.screenshot({ path: path.join(out, name), ...options });
  console.log("saved", name);
};
async function open(browser, port, size) {
  const context = await browser.newContext({ viewport: size, deviceScaleFactor: 2, locale: "ru-RU", timezoneId: "Europe/Moscow", colorScheme: "light" });
  await context.addInitScript(() => { try { localStorage.setItem("symport-language", "ru"); localStorage.removeItem("symport-theme"); } catch {} });
  const page = await context.newPage();
  lastPage = page;
  page.on("pageerror", (e) => console.error("PAGEERROR", e.message.slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") console.error("CONSOLE", m.text().slice(0, 400)); });
  page.setDefaultTimeout(20000);
  for (let i = 0; i < 60; i++) { try { await page.goto(`http://127.0.0.1:${port}/next/`); break; } catch { await new Promise((r) => setTimeout(r, 250)); } }
  return page;
}
async function journal(page) {
  // A few real, harmless operations so the 7-day chart shows the actual journal.
  await page.evaluate(async () => {
    const token = document.querySelector("meta[name=symport-token]").content;
    for (const path of ["Screenshots", "Backups", "Ringtones"])
      await fetch("/api/manager", { method: "POST", headers: { "Content-Type": "application/json", "X-Symport-Token": token },
        body: JSON.stringify({ action: "mkdir", device: "card", path, confirm: true }) });
  });
}
(async () => {
  let browser;
  try {
    start(tmp, "E52", "RM-469", 8801);
    start(tmp, "E72", "RM-530", 8802);
    browser = await chromium.launch({ headless: true, ...(process.env.SYMPORT_BROWSER_EXECUTABLE ? { executablePath: process.env.SYMPORT_BROWSER_EXECUTABLE } : {}), args: ["--no-sandbox"] });
    const desktop = { width: 1280, height: 860 };
    for (const [model, port] of [["E52", 8801], ["E72", 8802]]) {
      const page = await open(browser, port, desktop);
      await page.getByRole("heading", { name: new RegExp("Nokia " + model) }).first().waitFor();
      await journal(page);
      await page.reload();
      await page.getByRole("heading", { name: new RegExp("Nokia " + model) }).first().waitFor();
      // The phone reports no storage counters; link the test card volume explicitly, as a user would.
      await page.locator("#page-phone-overview select").selectOption("card");
      await page.waitForTimeout(1500);
      await shot(page, `overview-${model.toLowerCase()}.png`, { fullPage: true });
      await page.context().close();
    }
    // E52 for everything else.
    const page = await open(browser, 8801, desktop);
    await page.getByRole("heading", { name: /Nokia E52/ }).first().waitFor();
    const go = async (route) => {
      await page.evaluate((h) => { location.hash = "#" + h; }, route);
      await page.locator("#page-" + route.replace("/", "-")).waitFor();
      await page.waitForTimeout(300);
    };
    await go("phone/connection");
    await page.locator(".wizard-step[data-step='capabilities'][data-status='success']").waitFor();
    await shot(page, "connection-wizard.png", { clip: { x: 0, y: 0, width: 1280, height: 860 } });
    await go("apps/catalog");
    await page.locator(".catalog-app").first().waitFor();
    await shot(page, "catalog.png");
    const mode = (name) => page.locator(`.mode-switch button[data-mode="${name}"]`).click();
    await mode("developer"); // firmware and dependency pages belong to developer mode
    await go("tools/firmware");
    const firmware = page.locator("#page-tools-firmware");
    await firmware.locator("input[type=file]").first().setInputFiles(path.join(tmp, "fw-a.zip"));
    await firmware.locator("button.primary").first().click();
    await firmware.getByText(/Готов|Ready/).first().waitFor();
    await firmware.getByRole("button", { name: /^sys/ }).first().click();
    await firmware.getByRole("button", { name: /^bin/ }).first().click();
    await firmware.getByRole("button", { name: "app.exe" }).click();
    await firmware.getByText(/Secure ID/).first().waitFor();
    await shot(page, "firmware.png");
    await go("apps/dependencies");
    const deps = page.locator("#page-apps-dependencies");
    await deps.locator("input[type=file]").first().setInputFiles(path.join(tmp, "demo-app.sis"));
    await deps.locator("button.primary").first().click();
    await deps.getByText(/Qt/).first().waitFor();
    await shot(page, "dependencies.png");
    await mode("user"); // everything else is shown the way a user sees it
    await go("revive/home");
    await page.getByText("Прочитано с устройства").first().waitFor();
    await shot(page, "revive.png", { clip: { x: 0, y: 0, width: 1280, height: 1100 } });
    await go("apps/kits");
    await page.locator("#essentials").waitFor();
    await shot(page, "kits.png", { clip: { x: 0, y: 0, width: 1280, height: 1000 } });
    await go("personalize/ringtones");
    await shot(page, "ringtone.png");
    await go("personalize/theme-editor");
    await shot(page, "theme-studio.png");
    await go("tools/diagnostics");
    await shot(page, "diagnostics.png");
    await page.getByRole("button", { name: "Настройки", exact: true }).click();
    await page.getByLabel("Компактное меню (только значки)").check();
    await page.getByRole("button", { name: "Настройки", exact: true }).click();
    await page.setViewportSize({ width: 1280, height: 1180 }); // the whole menu fits next to the footer
    await go("personalize/wallpapers");
    await shot(page, "planned-compact.png");
    await page.setViewportSize(desktop);
    await go("phone/files");
    await page.locator("#page-phone-files select").first().selectOption("card");
    await page.locator(".phone-files").getByText("Images").first().waitFor();
    await shot(page, "files.png");
    await page.context().close();
    const mobile = await open(browser, 8801, { width: 390, height: 844 });
    await mobile.getByRole("heading", { name: /Nokia E52/ }).first().waitFor();
    await shot(mobile, "overview-mobile.png", { fullPage: true });
    await mobile.context().close();
  } catch (error) {
    try { console.error((await lastPage.locator("main").innerText()).slice(0, 800)); } catch {}
    throw error;
  } finally {
    await browser?.close();
    stopFixture();
    fs.rmSync(tmp, { recursive: true, force: true });
  }
})().catch((error) => { console.error(error); process.exitCode = 1; });
